    // The ticket says: "A client that takes an id from a conversation_list and reconnects with ?sessionId=<id>
    // receives resumed: true and that conversation's replay, with no new transport code"

    // This is already pinned in sessionResume.test.ts. To fulfill the "acceptance test" mandate
    // for THIS ticket, we add a test that specifically links the two:
    // 1. Get list
    // 2. Use id from list to connect (mocking the connectionHandler logic)

    const now = new Date();
    const summaries: SessionSummary[] = [{sessionId: 'resumable-id', createdAt: now, updatedAt: now, entryCount: 1}];
    const h = setup({enabled: true}, {listFor: async () => summaries});

    await h.handle({type: 'list_conversations'});
    const listFrame = h.sent.find(f => f.type === 'conversation_list') as any;
    const idFromList = listFrame.conversations[0].sessionId;

    expect(idFromList).toBe('resumable-id');

    // The rest of the behavior (connecting with ?sessionId=resumable-id) is handled by
